import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.DSc8fo6x.js";const g=JSON.parse('{"title":"Если что-то не получается","description":"","frontmatter":{},"headers":[],"relativePath":"ru/problemler.md","filePath":"ru/problemler.md"}'),o={name:"ru/problemler.md"};function l(n,t,s,h,m,i){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="если-что-то-не-получается" tabindex="-1">Если что-то не получается <a class="header-anchor" href="#если-что-то-не-получается" aria-label="Permalink to &quot;Если что-то не получается&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Ситуация</th><th>Что делать</th></tr></thead><tbody><tr><td>Белый экран / «На экране произошла ошибка»</td><td><strong>Перезагрузить</strong> или закройте окно и откройте снова. Продажи не пропадут.</td></tr><tr><td>«Товар не найден»</td><td>Этого товара нет в системе — пусть админ его <a href="./mallar.html">добавит</a>.</td></tr><tr><td>Сканер не считывает</td><td>Проверьте кабель сканера. Отсканируйте в Блокноте: должны появиться цифры. Если штрихкод порван или стёрт — найдите товар по названию.</td></tr><tr><td>Принтер не печатает</td><td><a href="./printerler.html#problemler">Принтер → Проблемы</a>.</td></tr><tr><td>Забыл пароль</td><td>Пусть админ задаст новый в разделе <a href="./istifadeciler.html">Пользователи</a>. Если забыл сам админ — к техническому специалисту.</td></tr><tr><td>«Слишком много неудачных попыток»</td><td>Подождите 1 минуту или пусть админ нажмёт <strong>Разблокировать</strong>.</td></tr><tr><td>Программа не открывается, пишет ошибку</td><td>Сфотографируйте сообщение и отправьте техническому специалисту.</td></tr><tr><td>Открылся экран <strong>Восстановление</strong></td><td><a href="./backup.html#berpa-ekrani">Бэкап и восстановление → Экран восстановления</a>. Нужен код восстановления.</td></tr><tr><td>Красное «В базе обнаружено повреждение»</td><td>Продавать можно дальше. Как можно скорее сообщите техническому специалисту — может понадобиться восстановление из последнего бэкапа.</td></tr><tr><td>Жёлтое «Бэкап в Telegram не отправляется»</td><td><a href="./telegram.html">Telegram</a>.</td></tr><tr><td>«Часы компьютера неверны»</td><td>Исправьте дату и время в Windows (чтобы продажи не попали не на ту дату).</td></tr><tr><td>При удалении/обновлении пишет «Касса сейчас открыта»</td><td>Закройте окно Kassa, подождите 2 секунды, <strong>OK</strong>.</td></tr><tr><td>Компьютер сломался</td><td><a href="./backup.html#komputer-xarab-oldu">Бэкап → Компьютер сломался</a>.</td></tr></tbody></table><h2 id="показать-проблему-разработчику" tabindex="-1">Показать проблему разработчику <a class="header-anchor" href="#показать-проблему-разработчику" aria-label="Permalink to &quot;Показать проблему разработчику&quot;">​</a></h2><p>Нажмите на своё имя слева внизу → <strong>Сообщить о проблеме</strong> → <strong>Скачать файл</strong> (или <strong>Отправить в Telegram</strong>) → отправьте файл через WhatsApp/Telegram. В файле <strong>нет</strong> продаж и цен.</p>',4)])])}const _=r(o,[["render",l]]);export{g as __pageData,_ as default};
